import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
const $=id=>document.getElementById(id);
const el=$('scene'),mobile=()=>innerWidth<621;
const scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x0a1926,.012);
const camera=new THREE.PerspectiveCamera(42,1,.1,180);
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});}catch(e){$('loading').textContent='This view needs a browser with WebGL enabled.';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor(0x08141f,0);el.prepend(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.065;controls.minDistance=3;controls.maxDistance=65;controls.maxPolarAngle=Math.PI*.46;controls.minPolarAngle=.12;controls.enablePan=true;
scene.add(new THREE.HemisphereLight(0xb5e5ef,0x122934,2.1));const sun=new THREE.DirectionalLight(0xd7eef1,2.3);sun.position.set(-12,23,-12);scene.add(sun);
const world=new THREE.Group();scene.add(world);
let meta,heights,routes,networks=[],selected=null,routeLine=null,routeGlow=null,particles=null,cumulative=[],total=0,playing=false,progress=0,last=0,autoMove=false,targetCam=new THREE.Vector3(),targetLook=new THREE.Vector3();
const traveler=new THREE.Mesh(new THREE.SphereGeometry(.065,16,12),new THREE.MeshBasicMaterial({color:0xffe2ae,depthTest:false}));traveler.renderOrder=6;traveler.visible=false;world.add(traveler);
let activeLabels=[],staticLabels=[];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){const w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.setViewOffset(w,h,mobile()?0:-Math.min(160,w*.12),0,w,h);camera.updateProjectionMatrix();}
new ResizeObserver(resize).observe(el);
function home(immediate=false){const pos=new THREE.Vector3(4,33,32);if(mobile())pos.set(2,43,33);targetLook.set(0,0,0);targetCam.copy(pos);if(immediate){camera.position.copy(pos);controls.target.set(0,0,0);}else autoMove=true;}
home(true);
function height(lon,lat){const xx=(lon-64)/35*(meta.nx-1),yy=(38-lat)/34*(meta.ny-1),x=Math.max(0,Math.min(meta.nx-2,Math.floor(xx))),y=Math.max(0,Math.min(meta.ny-2,Math.floor(yy))),dx=Math.max(0,Math.min(1,xx-x)),dy=Math.max(0,Math.min(1,yy-y)),i=y*meta.nx+x;return Math.max(0,heights[i]*(1-dx)*(1-dy)+heights[i+1]*dx*(1-dy)+heights[i+meta.nx]*(1-dx)*dy+heights[i+meta.nx+1]*dx*dy)*.0004;}
function geo(lon,lat,offset=.04){return new THREE.Vector3((lon-81.5)*Math.cos(23*Math.PI/180),height(lon,lat)+offset,21-lat);}
function line(points,color,opacity=1){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(points.flat(),3));return new THREE.Line(geometry,new THREE.LineBasicMaterial({color,transparent:true,opacity,depthWrite:false}));}
function label(text,lon,lat,type=''){const node=document.createElement('span');node.className='geo-label '+type;node.textContent=text;$('labels').append(node);const item={node,pos:geo(lon,lat,.15)};return item;}
function clearLabels(){for(const l of activeLabels)l.node.remove();activeLabels=[];}
function dispose(obj){if(!obj)return;world.remove(obj);obj.geometry?.dispose();obj.material?.dispose();}
function drawTerrain(){const nx=meta.nx,ny=meta.ny,positions=new Float32Array(nx*ny*3),colors=new Float32Array(nx*ny*3),indexes=[];const low=new THREE.Color('#275460'),mid=new THREE.Color('#3c6866'),high=new THREE.Color('#a8b9b7'),snow=new THREE.Color('#d2e0df'),water=new THREE.Color('#0f2a3b'),col=new THREE.Color();for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const i=y*nx+x,h=heights[i];positions.set([(x/(nx-1)*35-17.5)*Math.cos(23*Math.PI/180),Math.max(0,h)*.0004,17-y/(ny-1)*34].map((v,j)=>j===2?-v:v),i*3);if(h<=0)col.copy(water);else if(h<1200)col.copy(low).lerp(mid,h/1200);else if(h<4500)col.copy(mid).lerp(high,(h-1200)/3300);else col.copy(high).lerp(snow,Math.min(1,(h-4500)/2200));colors.set([col.r,col.g,col.b],i*3);if(x<nx-1&&y<ny-1){indexes.push(i,i+nx,i+1,i+1,i+nx,i+nx+1);}}
const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(positions,3));g.setAttribute('color',new THREE.BufferAttribute(colors,3));g.setIndex(indexes);g.computeVertexNormals();world.add(new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,metalness:.05,side:THREE.DoubleSide})));
const sea=new THREE.Mesh(new THREE.PlaneGeometry(150,150),new THREE.MeshBasicMaterial({color:0x0c2332,transparent:true,opacity:.5}));sea.rotation.x=-Math.PI/2;sea.position.y=-.05;scene.add(sea);
}
function renderLand(land){for(const f of land){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[];for(const poly of polys){const pts=poly[0].map(c=>geo(...c,.035).toArray());world.add(line(pts,f.name==='India'?0xa3ced0:0x6d8997,f.name==='India'?.42:.18));}}}
function selectRiver(id){selected=routes.find(r=>r.id===id)||null;$('river').value=selected?.id||'all';playing=false;progress=0;autoMove=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play journey');$('progress').value=0;clearLabels();dispose(routeLine);dispose(routeGlow);dispose(particles);routeLine=routeGlow=particles=null;document.body.classList.remove('travelling');document.body.classList.toggle('river-selected',!!selected);traveler.visible=!!selected;$('journey').hidden=!selected;networks.forEach((n,i)=>n.material.opacity=selected?[.14,.22,.36][i]:[.22,.48,.85][i]);
if(!selected){$('river-info').innerHTML='<h2>Many sources. One landscape.</h2><p>From Himalayan glaciers to the Western Ghats, follow the water as small streams join larger rivers.</p>';$('follow').innerHTML='Follow the Ganga <span>↗</span>';home();return;}
$('river-info').innerHTML=`<h2>${selected.name}</h2><p>${selected.description}</p><div class="point-note">${selected.source}</div>`;$('follow').innerHTML='Start river journey <span>↗</span>';
routeLine=line(selected.path,0xffc785);routeLine.material.depthTest=false;routeLine.renderOrder=3;world.add(routeLine);
const glowGeo=new THREE.BufferGeometry();glowGeo.setAttribute('position',new THREE.Float32BufferAttribute(selected.path.flat(),3));routeGlow=new THREE.Points(glowGeo,new THREE.PointsMaterial({color:0xffb969,size:.065,transparent:true,opacity:.6,depthTest:false,depthWrite:false}));world.add(routeGlow);
cumulative=[0];for(let i=1;i<selected.path.length;i++){const a=selected.path[i-1],b=selected.path[i];cumulative.push(cumulative.at(-1)+Math.hypot(b[0]-a[0],b[2]-a[2]));}total=cumulative.at(-1);
const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(new Float32Array(30*3),3));particles=new THREE.Points(g,new THREE.PointsMaterial({color:0xfff1cf,size:.11,transparent:true,opacity:1,depthTest:false,depthWrite:false}));particles.renderOrder=5;world.add(particles);
const first=selected.coordinates[0];activeLabels.push(label(selected.source,...first,'source'));const end=selected.coordinates.at(-1);activeLabels.push(label(selected.id==='luni'?'Mapped outlet · Rann drainage':'Mapped outlet · estuary / coast',...end,'source'));addMilestones();updateProgress(0);home();
}
const checkpointData={ganga:[['Devprayag · Alaknanda joins',78.60,30.15],['Prayagraj · Yamuna joins',81.88,25.43],['Varanasi',83.01,25.31],['Patna',85.15,25.62]],brahmaputra:[['Eastern Himalayan bend',95.0,29.72],['Siang · entering Assam',95.35,28.1],['Guwahati',91.74,26.18],['Jamuna · Bangladesh',89.7,24.6]],yamuna:[['Delhi',77.25,28.65],['Agra',78.04,27.19],['Prayagraj · joins the Ganga',81.88,25.43]],godavari:[['Nashik',73.79,20.0],['Nanded',77.31,19.15],['Rajamahendravaram',81.76,17.0]],krishna:[['Tungabhadra confluence',78.26,15.95],['Vijayawada',80.61,16.5]],narmada:[['Jabalpur region',79.94,23.1],['Bharuch',72.99,21.69]],kaveri:[['Srirangapatna',76.69,12.43],['Tiruchirappalli',78.69,10.85]],indus:[['Ladakh',77.58,34.1],['Punjab tributaries join',70.7,29.1]],mahanadi:[['Hirakud region',83.86,21.52],['Cuttack',85.88,20.49]]};
let milestones=[];
function addMilestones(){milestones=[];for(const [name,lon,lat] of checkpointData[selected.id]||[]){let idx=0,best=Infinity;selected.coordinates.forEach((p,i)=>{const d=(p[0]-lon)**2+(p[1]-lat)**2;if(d<best){idx=i;best=d;}});if(best<.3){milestones.push({name,t:cumulative[idx]/total});activeLabels.push(label(name,...selected.coordinates[idx],'river'));}}milestones.sort((a,b)=>a.t-b.t);}
function pointAt(t){const d=Math.min(1,Math.max(0,t))*total;let lo=0,hi=cumulative.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(cumulative[mid]<d)lo=mid+1;else hi=mid;}const i=Math.max(1,lo),a=selected.path[i-1],b=selected.path[i],f=(d-cumulative[i-1])/(cumulative[i]-cumulative[i-1]||1);return new THREE.Vector3(...a).lerp(new THREE.Vector3(...b),f);}
function updateProgress(t){progress=t;$('progress').value=Math.round(t*1000);$('progress-label').textContent=Math.round(t*100)+'%';let stage=t<.035?'Mapped headwaters':t>.98?'Mapped outlet · '+selected.outlet:milestones.filter(m=>m.t<=t+.015).at(-1)?.name||'Following the upper river';$('stage').textContent=stage;traveler.position.copy(pointAt(t));traveler.position.y+=.06;if($('track').checked&&document.body.classList.contains('travelling')){const p=pointAt(t);p.y*=world.scale.y;targetLook.copy(p);targetCam.copy(p).add(new THREE.Vector3(1.8,6.8,7.5));autoMove=true;}}
function start(){if(!selected)selectRiver('ganga');document.body.classList.add('travelling');$('track').checked=true;playing=!reduced;$('follow').innerHTML='Restart journey <span>↺</span>';$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause journey':'Play journey');updateProgress(0);}
$('river').addEventListener('change',e=>selectRiver(e.target.value));$('follow').onclick=start;
$('play').onclick=()=>{if(progress>=1)updateProgress(0);playing=!playing;document.body.classList.add('travelling');$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause journey':'Play journey');};
$('progress').oninput=e=>{playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play journey');document.body.classList.add('travelling');updateProgress(+e.target.value/1000);};
$('tributaries').onchange=e=>{networks[0].visible=e.target.checked;};$('relief').onchange=e=>{world.scale.y=e.target.checked?1:.015;};$('overview').onclick=()=>selectRiver('all');
$('zoom-in').onclick=()=>{autoMove=false;camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);};$('zoom-out').onclick=()=>{autoMove=false;camera.position.sub(controls.target).multiplyScalar(1.2).add(controls.target);};
controls.addEventListener('start',()=>{autoMove=false;$('track').checked=false;});$('track').onchange=()=>{if(selected)updateProgress(progress);};$('about').onclick=()=>$('about-dialog').showModal();$('close-about').onclick=()=>$('about-dialog').close();$('about-dialog').addEventListener('click',e=>{if(e.target===$('about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
async function init(){const get=async(u,type='json')=>{const r=await fetch(u);if(!r.ok)throw new Error('Could not load '+u);return type==='json'?r.json():r.arrayBuffer();};const result=await Promise.all([get('./data/metadata.json'),get('./data/elevation.bin','bin'),get('./data/land.json'),get('./data/routes.json'),...[0,1,2].map(i=>get(`./data/network-${i}.bin`,'bin'))]);[meta,, ,routes]=result;heights=new Float32Array(result[1]);drawTerrain();renderLand(result[2]);for(let i=0;i<3;i++){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(result[i+4]),3));const m=new THREE.LineBasicMaterial({color:i===2?0x9ae7ea:0x63bbd0,transparent:true,opacity:[.22,.48,.85][i],depthWrite:false});const n=new THREE.LineSegments(g,m);world.add(n);networks.push(n);}
for(const r of routes){const o=document.createElement('option');o.value=r.id;o.textContent=r.name+' · '+r.family;$('river').append(o);}staticLabels=[label('ARABIAN SEA',67.5,15,'sea'),label('BAY OF BENGAL',89.5,15,'sea'),label('INDIA',78.6,23,'country'),label('TIBETAN PLATEAU',87,33.5,'country'),label('NEPAL',84.3,28.5,'country'),label('PAKISTAN',68.8,28.8,'country'),label('SRI LANKA',80.8,7.4,'country'),label('H I M A L A Y A',83,30.7,'country')];$('coverage').textContent=meta.indiaReaches.toLocaleString('en-IN')+' mapped river reaches intersect India. Connected waterways continue across borders.';$('data-details').innerHTML=`<p>This view includes ${meta.indiaReaches.toLocaleString('en-IN')} HydroRIVERS reaches intersecting the Natural Earth India boundary, plus connected basins within the regional view. A reach is a section of river between junctions, not a separate named river.</p><p>HydroRIVERS maps channels with a catchment of at least 10 km² or average flow of at least 0.1 m³/s. Smaller streams, canals and many delta branches are absent. Its single downstream connection cannot reproduce every distributary. Lines are simplified for a national overview.</p><p>The ${routes.length} named journeys snap approximate source regions to mapped channels and follow the dataset's downstream links. A mapped headwater may be several kilometres from the named spring or glacier. Journeys on tributaries continue along the receiving river to the outlet.</p><p>Elevation is sampled from Mapzen tiles and exaggerated about 44×. Coarse terrain and river geometry may not align at close zoom. <a href="./data/hydro-license.pdf">HydroSHEDS terms and attribution</a> · <a href="./data/HydroRIVERS_TechDoc_v10.pdf">River dataset documentation</a></p>`;
$('loading').remove();resize();window.riverAtlas={selectRiver,start,getState:()=>({river:selected?.id||'all',progress,playing,indiaReaches:meta.indiaReaches}),routes:routes.map(r=>({id:r.id,name:r.name,complete:r.complete,reaches:r.reaches,terminal:r.terminal}))};registerTools();requestAnimationFrame(frame);}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();try{Promise.resolve(context.registerTool({name:'select_river',description:'Select a river in the 3D atlas and optionally start its downstream journey.',inputSchema:{type:'object',properties:{river:{type:'string',enum:['all',...routes.map(r=>r.id)]},start:{type:'boolean'}},required:['river'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.river!=='string'||!['all',...routes.map(r=>r.id)].includes(input.river)||('start'in input&&typeof input.start!=='boolean'))throw new Error('Choose a valid river and a boolean start value.');selectRiver(input.river);if(input.start&&input.river!=='all')start();return window.riverAtlas.getState();}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
function frame(time){const dt=Math.min(.05,(time-last)/1000||0);last=time;if(selected&&playing){updateProgress(Math.min(1,progress+dt/85));if(progress===1){playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Replay journey');}}if(autoMove){const speed=1-Math.exp(-dt*4);camera.position.lerp(targetCam,speed);controls.target.lerp(targetLook,speed);if(!playing&&camera.position.distanceTo(targetCam)<.015)autoMove=false;}controls.update();
if(particles&&selected){const a=particles.geometry.attributes.position;for(let i=0;i<a.count;i++){const t=reduced?i/a.count:(time*.000018+i/a.count)%1;const p=pointAt(t);a.setXYZ(i,p.x,p.y+.025,p.z);}a.needsUpdate=true;}
const view=camera.position.distanceTo(controls.target);for(const l of [...staticLabels,...activeLabels]){const p=l.pos.clone();p.y*=world.scale.y;p.project(camera);l.node.style.left=((p.x+1)/2*el.clientWidth)+'px';l.node.style.top=((-p.y+1)/2*el.clientHeight)+'px';l.node.style.display=p.z<1&&Math.abs(p.x)<.97&&Math.abs(p.y)<.95&&(!staticLabels.includes(l)||view>14)?'':'none';}renderer.render(scene,camera);requestAnimationFrame(frame);}
init().catch(err=>{console.error(err);$('loading').textContent='The map could not load. Please reload to try again.';});
